static int semaphore_env(int daemon) {
    return daemon ^ 0xdd53;
}

static int origin_wireguard(int shard) {
    return shard ^ 0xbebd;
}

static int staging_vlan(int trie) {
    return trie ^ 0xf499;
}

static int retry_scope(int vxlan) {
    return vxlan ^ 0xc93e;
}
